  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

* { box-sizing: border-box; }
body { margin: 0; padding: 24px; font-family: system-ui, sans-serif; background: #eef2f8; color: #182338; }
.demo { max-width: 760px; margin: auto; }
.demo__badge { color: #315fce; font-size: 11px; font-weight: 800; letter-spacing: .12em; }
.demo h2 { margin: 8px 0; font-size: 28px; }
.demo > p { color: #58657b; line-height: 1.6; }
.demo__cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 14px; margin-top: 24px; }
.demo-card { padding: 18px; border: 1px solid #d9e0ec; border-radius: 16px; background: white; box-shadow: 0 8px 24px #20365a12; }
.demo-card__icon { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 11px; background: #e8efff; color: #315fce; font-weight: 800; }
.demo-card h3 { margin: 14px 0 6px; }
.demo-card p { min-height: 42px; color: #657188; font-size: 13px; line-height: 1.5; }
.demo-card button { border: 0; border-radius: 8px; padding: 9px 12px; color: white; background: #315fce; cursor: pointer; }

